import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Sequence-Operator.md","filePath":"manual-zh/Matrix-Sequence-Operator.md","lastUpdated":1785684581000}'),s={name:"manual-zh/Matrix-Sequence-Operator.md"};function o(p,t,n,c,i,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h4 id="_16-4-1-2-整数序列运算符" tabindex="-1">16.4.1.2 整数序列运算符 ‘:’ <a class="header-anchor" href="#_16-4-1-2-整数序列运算符" aria-label="Permalink to &quot;16.4.1.2 整数序列运算符 ‘:’&quot;">​</a></h4><p>语法 <code>first:last:step</code> 产生一个由从 first 到 last、以 step 为步长的连续整数组成的行向量。最后的 <code>:step</code> 是可选的，省略时默认为 1。</p><p>first、last 和 step 各自必须是标量，且应为整数（任何小数部分被丢弃）。由于 “:” 优先级较高，非数字字面量的操作数通常必须加括号。</p><p>当 step 为正（或省略）且 <em>end &lt; start</em>，或 step 为负且 <em>end &gt; start</em> 时，结果为空矩阵。如果 step 为 0，则 PSPP 报错。</p><p>以下是一些示例：</p><table tabindex="0"><thead><tr><th>1:6</th><th>⇒</th><th>{1, 2, 3, 4, 5, 6}</th></tr></thead><tbody><tr><td>1:6:2</td><td>⇒</td><td>{1, 3, 5}</td></tr><tr><td>-1:-5:-1</td><td>⇒</td><td>{-1, -2, -3, -4, -5}</td></tr><tr><td>-1:-5</td><td>⇒</td><td>{}</td></tr><tr><td>2:1:0</td><td>⇒</td><td>(错误)</td></tr></tbody></table>',6)])])}const m=e(s,[["render",o]]);export{h as __pageData,m as default};
